typedef size_t Tag;
#define TAG_SIZE sizeof(Tag)
#define IS_USED 0x1

// Extracts the block size (lower bits reserved for status)
#define SIZE_FROM_TAG(tag) ((tag) & ~IS_USED)

// Given ptr P points to current Block Header (Tag):
void* P;

// Calculate location of the preceding block's footer
Tag* PREV_FOOTER(void* P) {
    return (Tag*)P - 1;
}

// Calculate location of the current block's footer
// S = total block size (including both tags)
Tag* CURRENT_FOOTER(void* P, size_t S) {
    return (Tag*)((char*)P + S - TAG_SIZE);
}

// Example Coalescing Check:
Tag prev_tag = *PREV_FOOTER(P);
if (!(prev_tag & IS_USED)) {
    size_t prev_sz = SIZE_FROM_TAG(prev_tag);
    P = (char*)P - prev_sz; // Move header to start of merged block
}
